def versioned_asset(filename):
 return filename+'?v='+hashlib.sha256((root/filename).read_bytes()).hexdigest()[:10]
for filename,body in contents.items():
 title=next((label for url,label in nav if url==filename),'Contact')
 html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="ASMD Lab at NIT Delhi: semiconductor materials, photovoltaic devices, research publications and people. Faculty: Dr. Rahul Pandey and Dr. Rikmantra Basu."><meta name="theme-color" content="#11283f"><title>'+title+' | ASMD Lab · NIT Delhi</title><link rel="icon" type="image/png" href="assets/nit-delhi-logo.png"><link rel="stylesheet" href="'+versioned_asset('styles.css')+'"><script defer src="'+versioned_asset('content.js')+'"></script><script defer src="'+versioned_asset('app.js')+'"></script></head><body>'+header(filename)+'<main id="main">'+body+'</main>'+footer()+'</body></html>'
 (root/filename).write_text(html)
print('Generated 8 public website pages and editable content file.')
